const MARK_PATTERN="(?<![A-Za-z0-9])(?:more\\\\ hard\\-working|most\\\\ hard\\-working|shortest|shorter|better|worst|best)(?![A-Za-z0-9])";


const MKCLS={"mk-er":1,"mk-est":1,"mk-than":1,"mk-more":1,"mk-the":1,"mk-most":1};
function colorize(txt,cm){
 if(!cm||!cm.length)return txt;
 const rules=cm.map(r=>({find:r[1],part:r[2]||"",cls:r[3]})).sort((a,b)=>b.find.length-a.find.length);
 const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const re=new RegExp('(?<![A-Za-z0-9])('+rules.map(r=>esc(r.find)).join('|')+')(?![A-Za-z0-9])','gi');
 let out='',last=0,mm;
 while((mm=re.exec(txt))){
  const rule=rules.find(r=>r.find.toLowerCase()===mm[0].toLowerCase());if(!rule)continue;
  out+=escapeHTML(txt.slice(last,mm.index));
  let pre='',core=mm[0],post='';
  if(rule.part){const p=rule.part;
   if(core.toLowerCase().endsWith(p.toLowerCase())){core=mm[0].slice(0,mm[0].length-p.length);post='';out+=escapeHTML(core);core='';out+='<span class="mk '+rule.cls+'">'+escapeHTML(mm[0].slice(mm[0].length-p.length))+'</span>';}
   else if(core.toLowerCase().startsWith(p.toLowerCase())){out+='<span class="mk '+rule.cls+'">'+escapeHTML(mm[0].slice(0,p.length))+'</span>';out+=escapeHTML(mm[0].slice(p.length));}
   else out+=escapeHTML(mm[0]);
  }else{out+='<span class="mk '+rule.cls+'">'+escapeHTML(mm[0])+'</span>';}
  last=mm.index+mm[0].length;re.lastIndex=last;
 }
 return out+escapeHTML(txt.slice(last));
}
function trowHTML(txt,head){
 const cells=txt.split('|');
 return '<div class="trow'+(head?' head':'')+'">'+cells.map((c,i)=>{
  const t=c.trim();if(/^[؀-ۿ]/.test(t))return '<span class="tcell ar">'+escapeHTML(t)+'</span>';
  const cls=i===1?'mk mk-more':(i===2?'mk mk-most':'');
  return '<span class="tcell en-cell" dir="ltr">'+(cls?'<span class="'+cls+'">'+escapeHTML(t)+'</span>':escapeHTML(t))+'</span>'}).join('')+'</div>';
}

function circleText(txt,marks){
 const allowed=new Set(marks.map(m=>m[1].toLowerCase()));const terms=[...allowed].sort((a,b)=>b.length-a.length).map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));if(!terms.length)return escapeHTML(txt);const re=new RegExp('(?<![A-Za-z0-9])(?:'+terms.join('|')+')(?![A-Za-z0-9])','gi');let out='',last=0,m;
 while((m=re.exec(txt))){if(!allowed.has(m[0].toLowerCase()))continue;out+=escapeHTML(txt.slice(last,m.index));const tail=(txt.slice(m.index+m[0].length).match(/^[,.;:!?]+/)||[''])[0];out+='<span class="red-key">'+escapeHTML(m[0]+tail)+'</span>';last=m.index+m[0].length+tail.length;re.lastIndex=last;}return out+escapeHTML(txt.slice(last));
}
function englishRuns(txt,render,sourceText=txt){
 // Classify the complete cue, not its briefly visible prefix during writing.
 const re=/[A-Za-z][A-Za-z0-9\s'’.,?!:;()_+\/→=–-]*/g;let out='',last=0,m;
 while((m=re.exec(sourceText))&&m.index<txt.length){
  out+=escapeHTML(txt.slice(last,m.index));
  const whole=m[0],visible=txt.slice(m.index,Math.min(txt.length,m.index+whole.length));
  const words=(whole.match(/[A-Za-z]+/g)||[]).length;
  const sentence=words>=3&&/^[A-Z]/.test(whole)&&(/[.?!]\s*$/.test(whole)||/^(?:I|He|She|They|We|You|It|Who|What|Where|When|Why|How|Did|Was|Were|Yesterday|After|Before|By|If)\b/.test(whole));
  const cls=words>=6||sentence?'english-run english-sentence':'english-run';
  out+='<bdi class="'+cls+'" dir="ltr">'+render(visible)+'</bdi>';last=m.index+visible.length;
 }
 return out+escapeHTML(txt.slice(last));
}
function optionChips(txt,hl){
 return txt.split(/\n| {2,}/).map(p=>{const w=p.trim();if(!w)return '';
  const on=hl&&(w.toLowerCase()===String(hl).toLowerCase()||w.toUpperCase().indexOf(String(hl).toUpperCase()+'.')===0);
  return '<span class="opt'+(on?' opt-correct':'')+'">'+escapeHTML(w)+'</span>'}).join(' ')}
function correctOpt(s,oId){
 const bi=s.blocks.findIndex(b=>b.id===oId);if(bi<0)return '';
 if(s.blocks[bi].answer)return s.blocks[bi].answer;
 for(let j=bi+1;j<s.blocks.length;j++){const cm=(s.colorMarks||[]).find(x=>x[0]===s.blocks[j].id&&x[3]==='mk-ans');if(cm)return cm[1];}
 return ''}
function markedText(txt,kind,marks,sourceText=txt,cm,hl=''){
 if(kind==='trow')return txt?trowHTML(txt,false):'';
 if(kind==='trow-head')return txt?trowHTML(txt,true):'';
 const wrap=t=>(cm&&cm.length)?colorize(t,cm):circleText(t,marks);
 if(kind==='options')return '<span class="english-line options-line" dir="ltr">'+optionChips(txt,hl)+'</span>';if((kind.includes('en')||kind==='options')&&!/[؀-ۿ]/.test(sourceText))return '<span class="english-line" dir="ltr">'+wrap(txt)+'</span>';
 return englishRuns(txt,wrap,sourceText)}

const $=id=>document.getElementById(id);let scene=0,playing=false,finished=false,epoch=0,raf=0,shown=-1,focusCard='';
const audio=new Audio();audio.preload='auto';let pace=.85;audio.defaultPlaybackRate=pace;audio.playbackRate=pace;audio.preservesPitch=true;function setPace(v){pace=Number(v);audio.defaultPlaybackRate=pace;audio.playbackRate=pace;draw(scene,audio.src?audio.currentTime/scenes[scene].duration:1)}const sources=new Map();
const total=()=>scenes.reduce((v,s)=>v+s.duration,0),startOf=i=>scenes.slice(0,i).reduce((v,s)=>v+s.duration,0),fmt=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function mixed(s){return englishRuns(s,escapeHTML)}
function pinHTML(i){const s=scenes[i];if(s.blocks.some(b=>b.kind==='en'||b.kind.indexOf('trow')===0))return '';for(let j=i-1;j>=0;j--){const t=scenes[j],ec=t.cues.filter(c=>{const b=t.blocks.find(x=>x.id===c[0]);return b&&b.kind==='en'});if(!ec.length)continue;const cue=[...ec].reverse().find(c=>c[1].trim().split(/\s+/).length>=3)||ec[ec.length-1];return '<section class="scene-card pin-card" id="card-pin-'+i+'"><div class="label">آخر مثال</div><div id="pin-'+i+'" class="en">'+markedText(cue[1],'en',t.wordMarks.filter(m=>m[0]===cue[0]),cue[1],(t.colorMarks||[]).filter(m=>m[0]===cue[0]))+'</div></section>'}return ''}
function ensurePart(i){let p=$('part-'+i);if(!p){const s=scenes[i];p=document.createElement('div');p.className='scene-part';p.id='part-'+i;p.innerHTML='<h2 class="scene-heading">'+mixed(s.label)+'</h2>'+s.blocks.map(b=>'<section class="scene-card'+(b.wrong?' wrong-x':'')+'" id="card-'+b.id+'"><div class="label">'+escapeHTML(b.label)+'</div><div id="'+b.id+'" class="'+b.kind+'"></div></section>').join('')+pinHTML(i);$('scene-board').appendChild(p)}return p}
function setScene(i,frac){const s=scenes[i];for(const c of s.cues){const el=$(c[0]),txt=c[1].slice(0,Math.ceil(c[1].length*frac)),kind=s.blocks.find(b=>b.id===c[0]).kind,html=frac>0?markedText(txt,kind,s.wordMarks.filter(m=>m[0]===c[0]&&frac>=m[2]),c[1],(s.colorMarks||[]).filter(m=>m[0]===c[0]&&frac>=(m[4]||0)),frac>=1?correctOpt(s,c[0]):''):'';if(el._html!==html){el.innerHTML=html;el._html=html}$('card-'+c[0]).hidden=!txt}}
function draw(i,f,scroll=false){const s=scenes[i];if(shown!==i){for(let k=0;k<i;k++){ensurePart(k);setScene(k,1)}for(let k=i+1;k<scenes.length;k++){const p=$('part-'+k);if(p)p.remove()}ensurePart(i);setScene(i,0);shown=i;focusCard='';$('caption').textContent=s.script;$('chapters').value=i;}
 let active='',activeAt=-1;for(const c of s.cues){const el=$(c[0]),part=Math.max(0,Math.min(1,(f-c[2])/(c[3]-c[2]))),txt=c[1].slice(0,Math.ceil(c[1].length*part));const kind=s.blocks.find(b=>b.id===c[0]).kind;let html=markedText(txt,kind,s.wordMarks.filter(m=>m[0]===c[0]&&f>=m[2]),c[1],(s.colorMarks||[]).filter(m=>m[0]===c[0]&&f>=(m[4]||0)),f>=c[3]?correctOpt(s,c[0]):'');
 if(el._html!==html){el.innerHTML=html;el._html=html}const card=$('card-'+c[0]);card.hidden=!txt;if(f>=c[2]&&(!active||c[2]>=activeAt)){active=card.id;activeAt=c[2];}}
 const elapsed=startOf(i)+f*s.duration;$('clock').textContent=fmt(elapsed/pace)+' / '+fmt(total()/pace);$('progress').value=Math.round(elapsed/total()*1000);$('scene-label').textContent=s.label;document.querySelectorAll('#play,.inline-play').forEach(b=>b.textContent=playing?'❚❚ إيقاف مؤقت':finished?'↺ أعد الشرح':audio.src?'▶ متابعة الشرح':'▶ ابدأ الشرح');
 if(scroll&&active&&active!==focusCard){focusCard=active;const el=$(active),r=el.getBoundingClientRect();if(r.top<0||r.bottom>innerHeight-90)el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}}
function frame(){if(!playing)return;draw(scene,Math.min(1,audio.currentTime/scenes[scene].duration),true);raf=requestAnimationFrame(frame)}
function source(i){if(!sources.has(i))sources.set(i,fetch('audio/'+scenes[i].audio+'?v=varied1').then(r=>{if(!r.ok)throw Error('Audio unavailable');return r.blob()}).then(b=>URL.createObjectURL(b)).catch(e=>{sources.delete(i);throw e}));return sources.get(i)}
async function load(i,at,e){const url=await source(i);if(e!==epoch)return false;await new Promise((resolve,reject)=>{audio.onloadedmetadata=resolve;audio.onerror=reject;audio.src=url});if(e!==epoch)return false;if(isFinite(audio.duration)&&audio.duration>2&&Math.abs(audio.duration-scenes[i].duration)>0.5)scenes[i].duration=audio.duration;audio.currentTime=at;audio.playbackRate=pace;return true}
async function start(i=scene,at=0){const e=++epoch;clearTimeout(window.__fbT);audio.pause();cancelAnimationFrame(raf);scene=i;finished=false;playing=true;$('done').hidden=true;draw(i,at/scenes[i].duration);const curPart=$('part-'+i);if(curPart)curPart.scrollIntoView({behavior:'smooth',block:'start'});try{if(!await load(i,at,e))return;await audio.play();if(e!==epoch)return;frame();if(i<scenes.length-1)source(i+1).catch(()=>{})}catch(err){if(e!==epoch)return;draw(i,1,true);clearTimeout(window.__fbT);window.__fbT=setTimeout(()=>{if(e!==epoch)return;if(i<scenes.length-1)start(i+1);else{playing=false;finished=true;cancelAnimationFrame(raf);draw(scene,1);$('done').hidden=false}},Math.min(9000,scenes[i].duration/pace*1000))}}
function pause(){playing=false;++epoch;clearTimeout(window.__fbT);audio.pause();cancelAnimationFrame(raf);draw(scene,audio.currentTime/scenes[scene].duration)}
function toggle(){if(playing)pause();else if(finished)restart();else if(!audio.src)start(scene);else{playing=true;const e=++epoch;audio.play().then(()=>{if(e===epoch)frame()}).catch(()=>{playing=false;draw(scene,audio.currentTime/scenes[scene].duration)})}}
function restart(){start(0)}function jump(i){start(i)}
function scrub(v){let at=Number(v)/1000*total(),i=0;while(i<scenes.length-1&&at>=scenes[i].duration)at-=scenes[i++].duration;const resume=playing;pause();scene=i;finished=false;$('done').hidden=true;draw(i,at/scenes[i].duration);if(resume)start(i,at);else{const e=epoch;load(i,at,e).catch(()=>{})}}
audio.addEventListener('ended',()=>{if(!playing)return;if(scene<scenes.length-1)start(scene+1);else{playing=false;finished=true;cancelAnimationFrame(raf);draw(scene,1);$('done').hidden=false}});
$('chapters').innerHTML=scenes.map((s,i)=>'<option value="'+i+'">'+escapeHTML(s.label)+'</option>').join('');draw(0,1);$('scene-label').textContent='جاهز للبدء';
